{
  "sop_id": "SOP-013",
  "title": "BOQ Review",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create BOQ ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Complete template checklist",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S2a",
      "name": "Verify each line has description, unit, quantity, and rate",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Check for missing or blank fields",
      "role": "System",
      "type": "decision"
    },
    {
      "step_id": "R1",
      "name": "Reject ticket if any field is missing or blank",
      "role": "System",
      "type": "rework"
    },
    {
      "step_id": "S3",
      "name": "Compare quantities to drawings and take-off",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Compare rates to schedule of rates and last three paid prices",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Record line-by-line variance",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Write summary of variance and highlight non-standard items",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S7",
      "name": "Submit BOQ for review",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D2",
      "name": "Check if site engineering confirmation on drawings/revision and take-off is pending",
      "role": "System",
      "type": "decision"
    },
    {
      "step_id": "D2a",
      "name": "Place ticket on DependencyWait if pending",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge review",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A1_condition",
      "name": "Approval condition",
      "role": "Incharge",
      "type": "decision"
    },
    {
      "step_id": "A1_condition_always",
      "name": "Always required",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R2",
      "name": "Reject ticket if Incharge rejects",
      "role": "System",
      "type": "rework"
    },
    {
      "step_id": "A2",
      "name": "Lead review (for big jobs, variance over 10%, or more than five non-standard items)",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "A2_condition",
      "name": "Approval condition",
      "role": "Lead",
      "type": "decision"
    },
    {
      "step_id": "A2_condition_always",
      "name": "Always required for big jobs, variance over 10%, or more than five non-standard items",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "A3",
      "name": "Lead review (for urgent jobs where site work has stopped)",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "A3_condition",
      "name": "Approval condition",
      "role": "Lead",
      "type": "decision"
    },
    {
      "step_id": "A3_condition_always",
      "name": "Always required for urgent jobs where site work has stopped",
      "role": "Lead",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "if job is above 25 lakh, variance over 10%, or more than five non-standard items"
    },
    {
      "stage": "Lead",
      "condition": "if job is urgent and site work has stopped"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Operations (Site Engineering)",
      "item": "Confirmation on drawing revision or take-off",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Wrong quantity",
    "Incorrect category",
    "Required document missing",
    "Amount mismatch"
  ],
  "first_pass_yield_target": 0.9
}
